public static class SteelTruckAssetBuilder {
 const string Root="Assets/_Anseong/Art/Environment/Assets/SteelTruck";
 static Material paint,steel,dark,amber;static readonly List<GameObject> chunks=new List<GameObject>();
 static void Folder(string path){if(AssetDatabase.IsValidFolder(path))return;string parent=Path.GetDirectoryName(path).Replace('\\','/');Folder(parent);AssetDatabase.CreateFolder(parent,Path.GetFileName(path));}
 static Material Mat(string name,Color color,float metallic=0){var m=AssetDatabase.LoadAssetAtPath<Material>(Root+"/"+name+".mat");if(m)return m;m=new Material(Shader.Find("Universal Render Pipeline/Lit"));m.color=color;m.SetFloat("_Metallic",metallic);m.SetFloat("_Smoothness",.25f);m.enableInstancing=true;AssetDatabase.CreateAsset(m,Root+"/"+name+".mat");return m;}
 static void Box(Transform root,string name,Vector3 pos,Vector3 size,Material mat){var g=GameObject.CreatePrimitive(PrimitiveType.Cube);g.name=name;g.transform.SetParent(root,false);g.transform.localPosition=pos;g.transform.localScale=size;g.GetComponent<Renderer>().sharedMaterial=mat;Object.DestroyImmediate(g.GetComponent<Collider>());chunks.Add(g);}
 static Mesh Ring(int sides,float outer,float inner,float length){var v=new List<Vector3>();var t=new List<int>();Vector3 P(int i,float radius,float x){float a=i*2*Mathf.PI/sides;return new Vector3(x,Mathf.Cos(a)*radius,Mathf.Sin(a)*radius);}void Q(Vector3 a,Vector3 b,Vector3 c,Vector3 d){int n=v.Count;v.AddRange(new[]{a,b,c,d});t.AddRange(new[]{n,n+1,n+2,n,n+2,n+3});}for(int i=0;i<sides;i++){Q(P(i,outer,-length/2),P(i+1,outer,-length/2),P(i+1,outer,length/2),P(i,outer,length/2));Q(P(i,inner,length/2),P(i+1,inner,length/2),P(i+1,inner,-length/2),P(i,inner,-length/2));Q(P(i,outer,length/2),P(i+1,outer,length/2),P(i+1,inner,length/2),P(i,inner,length/2));Q(P(i,inner,-length/2),P(i+1,inner,-length/2),P(i+1,outer,-length/2),P(i,outer,-length/2));}var mesh=new Mesh();mesh.SetVertices(v);mesh.SetTriangles(t,0);mesh.RecalculateNormals();return mesh;}
 static void Tube(Transform root,string name,Vector3 pos,Mesh mesh,Material mat){var g=new GameObject(name);g.transform.SetParent(root,false);g.transform.localPosition=pos;g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterial=mat;chunks.Add(g);}
 static Mesh Bake(Transform root){var materials=new[]{paint,steel,dark,amber};var groups=new List<Mesh>();var final=new CombineInstance[4];for(int i=0;i<4;i++){var list=new List<CombineInstance>();foreach(var part in chunks)if(part.GetComponent<Renderer>().sharedMaterial==materials[i])list.Add(new CombineInstance{mesh=part.GetComponent<MeshFilter>().sharedMesh,transform=root.worldToLocalMatrix*part.transform.localToWorldMatrix});var m=new Mesh();m.CombineMeshes(list.ToArray(),true,true);groups.Add(m);final[i]=new CombineInstance{mesh=m,transform=Matrix4x4.identity};}var result=new Mesh{name="SteelTruck_LowPoly"};result.CombineMeshes(final,false,true);result.RecalculateBounds();foreach(var m in groups)Object.DestroyImmediate(m);return result;}
 [MenuItem("Anseong/Art/Build Steel Truck %#F11")]
 public static void Build(){Folder(Root);paint=Mat("Cab_Ivory",new Color(.65f,.69f,.67f));steel=Mat("Steel",new Color(.28f,.32f,.34f),.55f);dark=Mat("Tires_Glass",new Color(.045f,.065f,.075f));amber=Mat("Safety_Amber",new Color(.85f,.42f,.06f));chunks.Clear();var root=new GameObject("SteelTruck");var r=root.transform;
  Box(r,"TractorChassis",new Vector3(0,.9f,4),new Vector3(2.3f,.4f,7.7f),dark);Box(r,"Cab",new Vector3(0,2.15f,5.9f),new Vector3(2.5f,2.8f,3.6f),paint);Box(r,"Roof",new Vector3(0,3.56f,5.5f),new Vector3(2.5f,.16f,2.8f),paint);Box(r,"Windshield",new Vector3(0,2.85f,7.72f),new Vector3(2.2f,.95f,.04f),dark);Box(r,"Grille",new Vector3(0,1.5f,7.73f),new Vector3(1.8f,.65f,.06f),dark);Box(r,"Bumper",new Vector3(0,.8f,7.83f),new Vector3(2.55f,.35f,.28f),steel);
  for(int side=-1;side<=1;side+=2){Box(r,"SideWindow",new Vector3(side*1.26f,2.85f,6.3f),new Vector3(.04f,.9f,1.8f),dark);Box(r,"Mirror",new Vector3(side*1.43f,2.75f,7.05f),new Vector3(.22f,.55f,.22f),steel);Box(r,"Step",new Vector3(side*1.15f,.62f,5.1f),new Vector3(.4f,.2f,1),steel);Box(r,"Headlight",new Vector3(side*.95f,1.08f,7.78f),new Vector3(.38f,.25f,.05f),amber);Box(r,"FuelTank",new Vector3(side*.97f,.8f,3.25f),new Vector3(.48f,.55f,1.1f),steel);}
  Box(r,"Flatbed",new Vector3(0,1.45f,-1.7f),new Vector3(2.55f,.25f,12.6f),steel);Box(r,"TrailerRails",new Vector3(0,1,-1.7f),new Vector3(1.2f,.5f,12.6f),dark);Box(r,"RearBumper",new Vector3(0,.65f,-8.03f),new Vector3(2.5f,.25f,.15f),amber);Box(r,"Headboard",new Vector3(0,2.05f,4.5f),new Vector3(2.5f,1,.15f),steel);
  var tire=Ring(12,.53f,.24f,.32f);var hub=Ring(12,.25f,.03f,.34f);foreach(float z in new[]{6.1f,2.55f,1.25f,-4.65f,-5.95f,-7.25f})for(int side=-1;side<=1;side+=2){Tube(r,"Tire",new Vector3(side*1.09f,.53f,z),tire,dark);Tube(r,"Hub",new Vector3(side*1.1f,.53f,z),hub,steel);}
  var coil=Ring(24,1,.32f,1.85f);foreach(float z in new[]{-5.25f,-1.9f,1.45f}){Box(r,"CoilCradle",new Vector3(0,1.68f,z),new Vector3(2.1f,.25f,1.3f),amber);Tube(r,"SteelCoil",new Vector3(0,2.65f,z),coil,steel);for(int side=-1;side<=1;side+=2)Box(r,"CargoStrap",new Vector3(side*.62f,3.66f,z),new Vector3(.05f,.035f,.55f),dark);}
  var mesh=Bake(r);string meshPath=Root+"/SteelTruck.asset";var existing=AssetDatabase.LoadAssetAtPath<Mesh>(meshPath);if(existing){EditorUtility.CopySerialized(mesh,existing);Object.DestroyImmediate(mesh);mesh=existing;}else AssetDatabase.CreateAsset(mesh,meshPath);foreach(var chunk in chunks)Object.DestroyImmediate(chunk);chunks.Clear();Object.DestroyImmediate(tire);Object.DestroyImmediate(hub);Object.DestroyImmediate(coil);root.AddComponent<MeshFilter>().sharedMesh=mesh;root.AddComponent<MeshRenderer>().sharedMaterials=new[]{paint,steel,dark,amber};var collider=root.AddComponent<BoxCollider>();collider.center=mesh.bounds.center;collider.size=new Vector3(2.55f,mesh.bounds.size.y,mesh.bounds.size.z);var prefab=PrefabUtility.SaveAsPrefabAsset(root,Root+"/SteelTruck.prefab");Object.DestroyImmediate(root);
  EditorSceneManager.NewScene(NewSceneSetup.DefaultGameObjects,NewSceneMode.Single);var instance=(GameObject)PrefabUtility.InstantiatePrefab(prefab);instance.transform.rotation=Quaternion.Euler(0,-25,0);var floor=GameObject.CreatePrimitive(PrimitiveType.Cube);floor.transform.position=new Vector3(0,-.1f,0);floor.transform.localScale=new Vector3(180,.2f,180);floor.GetComponent<Renderer>().sharedMaterial=steel;var camera=Camera.main;camera.transform.position=new Vector3(17,11,20);camera.transform.LookAt(new Vector3(0,1.6f,-.5f));camera.fieldOfView=38;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.25f,.34f,.42f);var sun=Object.FindFirstObjectByType<Light>();sun.intensity=2;sun.transform.rotation=Quaternion.Euler(45,-30,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color(.65f,.68f,.72f);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/_Anseong/Scenes/Sandbox/Sandbox_SteelTruck.unity");
  int tris=mesh.triangles.Length/3;if(tris>4000||mesh.bounds.size.z<15||mesh.bounds.size.z>17||prefab.GetComponentsInChildren<Rigidbody>().Length!=0)throw new Exception("Truck validation failed");AssetDatabase.SaveAssets();Capture(camera,"SteelTruck_Preview");Debug.Log("STEEL_TRUCK_TEST_PASS triangles="+tris+" dimensions="+mesh.bounds.size+" sharedMeshes=1 materials=4 rigidbodies=0");
 }
 static void Capture(Camera camera,string name){var texture=new RenderTexture(1200,800,24);var previous=RenderTexture.active;camera.targetTexture=texture;camera.Render();RenderTexture.active=texture;var image=new Texture2D(1200,800,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1200,800),0,0);image.Apply();File.WriteAllBytes("C:/Users/Admin/Documents/ChatGPT/안성제철/output/"+name+".png",image.EncodeToPNG());camera.targetTexture=null;RenderTexture.active=previous;Object.DestroyImmediate(image);Object.DestroyImmediate(texture);}
}
